sp_widget.css:
/* =========================================
   CAMPUSOPS — CLEAN STUDENT PORTAL
========================================= */

.co-home {
  --ink:#30264d;
  --muted:#807795;
  --purple:#8062c9;
  --line:#ece5f5;
  width:100%;
  color:var(--ink);
  font-family:Inter,"Segoe UI",Arial,sans-serif;
  font-size:13px;
  line-height:1.55;
}

.co-home * { box-sizing:border-box; }
.co-home a { text-decoration:none; }
.co-home a:focus-visible {
  outline:2px solid #8b6bd0;
  outline-offset:3px;
}

/* APP LAYOUT */

.co-home .co-app-layout {
  display:grid;
  grid-template-columns:218px minmax(0,1fr);
  align-items:stretch;
  gap:25px;
  width:100%;
}

/* LEFT SIDEBAR */

.co-home .co-sidebar {
  display:flex;
  flex-direction:column;
  min-width:0;
  min-height:690px;
  padding:20px 13px;
  border:1px solid #e9e0f5;
  border-radius:19px;
  background:linear-gradient(180deg,#f8f4ff 0%,#f3effb 100%);
}

.co-home .co-brand {
  display:flex;
  align-items:center;
  gap:10px;
  padding:4px 7px 24px;
  color:#382b54;
}

.co-home .co-brand-mark {
  display:grid;
  place-items:center;
  flex-shrink:0;
  width:37px;
  height:37px;
  border-radius:12px;
  background:#8062c9;
  color:white;
  font-size:19px;
  font-weight:800;
}

.co-home .co-brand > span:last-child {
  font-size:15px;
  font-weight:800;
  line-height:1.2;
}

.co-home .co-brand small {
  display:block;
  margin-top:4px;
  color:#8b7e9e;
  font-size:9px;
  font-weight:500;
}

.co-home .co-nav-label {
  padding:9px 10px;
  color:#a092b6;
  font-size:9px;
  font-weight:800;
  letter-spacing:1.15px;
}

.co-home .co-nav-spaced { margin-top:18px; }

.co-home .co-nav-item {
  display:flex;
  align-items:center;
  gap:11px;
  margin:2px 0;
  padding:11px 10px;
  border-radius:10px;
  color:#6e6382;
  font-size:11px;
  font-weight:600;
  transition:background .18s,color .18s,transform .18s;
}

.co-home .co-nav-item > span {
  display:grid;
  place-items:center;
  width:21px;
  flex-shrink:0;
  color:#8d79b5;
  font-size:16px;
  line-height:1;
}

.co-home .co-nav-item:hover {
  background:rgba(255,255,255,.8);
  color:#513a83;
  transform:translateX(2px);
}

.co-home .co-nav-active {
  background:#e8defa;
  color:#6245a0;
  font-weight:750;
}

.co-home .co-nav-active > span { color:#7354b4; }

.co-home .co-sidebar-bottom {
  margin-top:auto;
  padding-top:22px;
}

.co-home .co-sidebar-user {
  display:flex;
  align-items:center;
  gap:10px;
  padding:12px 8px 2px;
  border-top:1px solid #e4dbef;
}

.co-home .co-avatar {
  display:grid;
  place-items:center;
  flex-shrink:0;
  width:33px;
  height:33px;
  border-radius:50%;
  background:#e5daf8;
  color:#6549a1;
  font-weight:800;
}

.co-home .co-user-copy {
  min-width:0;
}

.co-home .co-user-copy strong,
.co-home .co-user-copy small {
  display:block;
  overflow-wrap:anywhere;
}

.co-home .co-user-copy strong {
  color:#49385f;
  font-size:10px;
}

.co-home .co-user-copy small {
  margin-top:3px;
  color:#9386a5;
  font-size:9px;
}

/* MAIN CONTENT */

.co-home .co-main {
  min-width:0;
}

.co-home .co-page-header {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:14px;
  margin:4px 0 24px;
}

.co-home .co-breadcrumb {
  color:#927bb7;
  font-size:9px;
  font-weight:800;
  letter-spacing:1.25px;
}

.co-home .co-page-header h1 {
  margin:9px 0 5px;
  color:#34264f;
  font-size:clamp(23px,2.5vw,32px);
  font-weight:800;
  letter-spacing:-.9px;
  line-height:1.25;
}

.co-home .co-page-header p {
  margin:0;
  color:#897d99;
  font-size:11px;
}

.co-home .co-header-profile {
  display:inline-flex;
  align-items:center;
  gap:9px;
  flex-shrink:0;
  padding:9px 12px;
  border:1px solid #e8def4;
  border-radius:10px;
  background:rgba(255,255,255,.75);
  color:#7356ad;
  font-size:10px;
  font-weight:700;
}

.co-home .co-header-profile:hover { background:white; }

/* RETURN NOTICE */

.co-home .co-notice {
  display:flex;
  align-items:center;
  gap:13px;
  margin-bottom:22px;
  padding:16px;
  border:1px solid #eadff9;
  border-radius:14px;
  background:linear-gradient(120deg,#f6f0ff,#fcf8ff);
}

.co-home .co-notice-overdue {
  border-color:#f0d5de;
  background:linear-gradient(120deg,#fff5f6,#fffafb);
}

.co-home .co-notice-mark {
  display:grid;
  place-items:center;
  flex-shrink:0;
  width:34px;
  height:34px;
  border-radius:10px;
  background:#e8defa;
  color:#7152b3;
  font-size:16px;
  font-weight:800;
}

.co-home .co-notice-overdue .co-notice-mark {
  background:#fbe3e9;
  color:#b34e6b;
}

.co-home .co-notice-copy { flex:1; min-width:0; }

.co-home .co-notice-copy strong {
  display:block;
  color:#433359;
  font-size:12px;
}

.co-home .co-notice-copy p {
  margin:4px 0 0;
  color:#81748f;
  font-size:10px;
  line-height:1.6;
}

.co-home .co-notice-detail {
  margin-top:6px;
  color:#7356ad;
  font-size:10px;
  font-weight:700;
}

.co-home .co-notice-link {
  flex-shrink:0;
  color:#7656b4;
  font-size:10px;
  font-weight:750;
}

/* BORROWING SUMMARY */

.co-home .co-summary {
  margin-bottom:23px;
  padding:18px;
  border:1px solid #ece5f5;
  border-radius:15px;
  background:rgba(255,255,255,.82);
  box-shadow:0 5px 18px rgba(79,60,118,.035);
}

.co-home .co-summary-heading,
.co-home .co-section-heading {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  margin-bottom:14px;
}

.co-home .co-summary-heading h2,
.co-home .co-section-heading h2 {
  margin:0;
  color:#403254;
  font-size:15px;
  font-weight:800;
  letter-spacing:-.25px;
}

.co-home .co-summary-heading p,
.co-home .co-section-heading p {
  margin:4px 0 0;
  color:#8c809b;
  font-size:10px;
}

.co-home .co-summary-heading > a,
.co-home .co-section-heading > a {
  flex-shrink:0;
  color:#7b5cba;
  font-size:10px;
  font-weight:750;
}

.co-home .co-summary-grid {
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
}

.co-home .co-stat {
  display:flex;
  flex-direction:column;
  gap:5px;
  padding:4px 12px;
  border-left:1px solid #eee7f6;
}

.co-home .co-stat:first-child {
  padding-left:0;
  border-left:0;
}

.co-home .co-stat:last-child { padding-right:0; }

.co-home .co-stat span {
  color:#887b98;
  font-size:10px;
}

.co-home .co-stat strong {
  color:#403052;
  font-size:24px;
  font-weight:800;
  line-height:1.2;
}

.co-home .co-stat .co-number-alert { color:#b95170; }

/* MAIN ACTIONS */

.co-home .co-actions {
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:11px;
  margin-bottom:25px;
}

.co-home .co-action-primary,
.co-home .co-action-secondary {
  display:flex;
  align-items:center;
  gap:11px;
  min-width:0;
  padding:15px 13px;
  border:1px solid #e4d8f5;
  border-radius:13px;
  background:#f7f2ff;
  transition:transform .2s,box-shadow .2s;
}

.co-home .co-action-secondary {
  background:#f7f8ff;
  border-color:#e0e0f6;
}

.co-home .co-action-primary:hover,
.co-home .co-action-secondary:hover {
  transform:translateY(-2px);
  box-shadow:0 7px 18px rgba(79,60,118,.07);
}

.co-home .co-action-symbol {
  display:grid;
  place-items:center;
  flex-shrink:0;
  width:32px;
  height:32px;
  border-radius:9px;
  background:rgba(255,255,255,.85);
  color:#7859b7;
  font-size:17px;
}

.co-home .co-action-primary > span:nth-child(2),
.co-home .co-action-secondary > span:nth-child(2) {
  flex:1;
  min-width:0;
}

.co-home .co-actions strong,
.co-home .co-actions small { display:block; }

.co-home .co-actions strong {
  color:#49385f;
  font-size:10px;
}

.co-home .co-actions small {
  margin-top:4px;
  color:#887b98;
  font-size:9px;
  line-height:1.5;
}

.co-home .co-action-arrow {
  flex-shrink:0;
  color:#8b70bf;
  font-size:16px;
}

/* CURRENT RENTALS */

.co-home .co-rentals {
  margin-bottom:22px;
}

.co-home .co-rental-list {
  overflow:hidden;
  border:1px solid #ece5f5;
  border-radius:13px;
  background:rgba(255,255,255,.84);
}

.co-home .co-rental-row {
  display:flex;
  align-items:center;
  gap:11px;
  min-width:0;
  padding:13px 12px;
  border-bottom:1px solid #f0ebf6;
  transition:background .15s;
}

.co-home .co-rental-row:last-child { border-bottom:0; }
.co-home .co-rental-row:hover { background:#fcfaff; }

.co-home .co-rental-icon {
  display:grid;
  place-items:center;
  flex-shrink:0;
  width:32px;
  height:32px;
  border-radius:9px;
  background:#f0e9fc;
  color:#7859b7;
  font-size:15px;
}

.co-home .co-rental-info {
  flex:1;
  min-width:0;
}

.co-home .co-rental-info strong,
.co-home .co-rental-info small {
  display:block;
  overflow-wrap:anywhere;
}

.co-home .co-rental-info strong {
  color:#49385f;
  font-size:10px;
}

.co-home .co-rental-info small {
  margin-top:3px;
  color:#a095b0;
  font-size:9px;
}

.co-home .co-rental-due {
  display:flex;
  flex-direction:column;
  gap:3px;
  flex-shrink:0;
}

.co-home .co-rental-due small {
  color:#9589a4;
  font-size:9px;
}

.co-home .co-rental-due strong {
  color:#625575;
  font-size:9px;
  font-weight:700;
}

.co-home .co-rental-due .co-text-overdue { color:#b95170; }
.co-home .co-rental-due .co-text-soon { color:#b27a2b; }

.co-home .co-status {
  flex-shrink:0;
  padding:4px 8px;
  border-radius:20px;
  font-size:9px;
  font-weight:750;
  white-space:nowrap;
}

.co-home .co-status-active { background:#eaf7ef;color:#4c956f; }
.co-home .co-status-soon { background:#fff4de;color:#a8762d; }
.co-home .co-status-overdue { background:#fce8ed;color:#b34e6b; }

/* EMPTY STATE */

.co-home .co-empty {
  padding:24px 15px;
  border:1px dashed #e4d8f1;
  border-radius:13px;
  background:#fcfaff;
  text-align:center;
}

.co-home .co-empty strong {
  color:#49385f;
  font-size:12px;
}

.co-home .co-empty p {
  margin:6px 0 11px;
  color:#887b98;
  font-size:10px;
}

.co-home .co-empty a {
  color:#7959b8;
  font-size:10px;
  font-weight:750;
}

/* HELP */

.co-home .co-help {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  padding:15px 16px;
  border:1px solid #e8e0f1;
  border-radius:13px;
  background:#faf7ff;
}

.co-home .co-help strong {
  color:#49385f;
  font-size:11px;
}

.co-home .co-help p {
  margin:4px 0 0;
  color:#887b98;
  font-size:10px;
}

.co-home .co-help > a {
  flex-shrink:0;
  color:#7959b8;
  font-size:10px;
  font-weight:750;
}

/* FOOTER */

.co-home .co-footer {
  margin-top:28px;
  padding:18px 2px 5px;
  border-top:1px solid #e9e2f1;
}

.co-home .co-footer-main {
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
}

.co-home .co-footer-main strong {
  color:#55416f;
  font-size:11px;
}

.co-home .co-footer-main span {
  color:#988ca8;
  font-size:9px;
}

.co-home .co-footer-links {
  display:flex;
  flex-wrap:wrap;
  gap:16px;
  margin-top:13px;
}

.co-home .co-footer-links a {
  color:#796a8d;
  font-size:10px;
}

.co-home .co-footer-links a:hover { color:#6748a8; }

.co-home .co-footer-copy {
  margin-top:13px;
  color:#a399b1;
  font-size:9px;
}

/* RESPONSIVE */

@media(max-width:850px) {
  .co-home .co-app-layout {
    grid-template-columns:175px minmax(0,1fr);
    gap:16px;
  }

  .co-home .co-sidebar { padding:15px 9px; }
  .co-home .co-nav-item { gap:8px;padding:10px 8px; }
  .co-home .co-header-profile { display:none; }
}

@media(max-width:620px) {
  .co-home .co-app-layout { grid-template-columns:1fr;gap:18px; }

  .co-home .co-sidebar {
    min-height:0;
    padding:12px;
    border-radius:14px;
  }

  .co-home .co-brand { padding-bottom:12px; }

  .co-home .co-sidebar .co-nav-label,
  .co-home .co-sidebar-bottom { display:none; }

  .co-home .co-sidebar {
    display:grid;
    grid-template-columns:repeat(2,minmax(0,1fr));
    align-content:start;
    gap:3px;
  }

  .co-home .co-brand { grid-column:1/-1; }

  .co-home .co-nav-item {
    margin:0;
    padding:9px;
    font-size:10px;
  }

  .co-home .co-page-header h1 { font-size:25px; }
  .co-home .co-notice { flex-wrap:wrap; }
  .co-home .co-notice-link { margin-left:47px; }
  .co-home .co-actions { grid-template-columns:1fr; }
  .co-home .co-summary { padding:14px; }
  .co-home .co-stat { padding:4px 8px; }
  .co-home .co-stat span { font-size:9px; }
  .co-home .co-stat strong { font-size:21px; }

  .co-home .co-rental-row { flex-wrap:wrap; }
  .co-home .co-rental-info { min-width:calc(100% - 55px); }
  .co-home .co-rental-due { margin-left:43px; }
  .co-home .co-help { align-items:flex-start;flex-direction:column; }
  .co-home .co-footer-main { align-items:flex-start;flex-direction:column; }
}

@media(max-width:380px) {
  .co-home .co-page-header h1 { font-size:22px; }
  .co-home .co-summary-grid { grid-template-columns:1fr;gap:9px; }
  .co-home .co-stat {
    flex-direction:row;
    justify-content:space-between;
    align-items:center;
    padding:7px 0;
    border-left:0;
    border-bottom:1px solid #eee7f6;
  }
  .co-home .co-stat:last-child { border-bottom:0; }
  .co-home .co-stat strong { font-size:18px; }
}

sp_widget.script:
(function() {
  var userId = gs.getUserID();
  var nowMs = new GlideDateTime().getNumericValue();
  var DAY_MS = 86400000;

  data.studentName = gs.getUserDisplayName() || "there";
  data.activeCount = 0;
  data.dueSoonCount = 0;
  data.overdueCount = 0;
  data.returnedCount = 0;
  data.nextRental = null;
  data.rentals = [];
  data.requests = [];
  data.locations = [];
  data.recommendations = [];

  function fmt(value) {
    if (!value) return "";
    try {
      return new GlideDateTime(value).getLocalDate().getByFormat("dd MMM yyyy");
    } catch (e) {
      return "";
    }
  }

  function daysUntil(value) {
    if (!value) return null;
    return Math.ceil(
      (new GlideDateTime(value).getNumericValue() - nowMs) / DAY_MS
    );
  }

  // Active rentals for the signed-in student.
  var rental = new GlideRecord("u_student_rental");
  rental.addQuery("u_student", userId);
  rental.addQuery("u_status", "active");
  rental.orderBy("u_due_date");
  rental.query();

  while (rental.next()) {
    data.activeCount++;

    var dueValue = rental.getValue("u_due_date");
    var daysLeft = daysUntil(dueValue);
    var isOverdue = dueValue &&
      new GlideDateTime(dueValue).getNumericValue() < nowMs;
    var isDueSoon = !isOverdue && daysLeft !== null &&
      daysLeft >= 0 && daysLeft <= 2;

    if (isOverdue) {
      data.overdueCount++;
    } else if (isDueSoon) {
      data.dueSoonCount++;
    }

    var assetName = rental.getDisplayValue("u_asset") || "Campus resource";
    var rentalDate = rental.getValue("u_rental_date");

    var entry = {
      id: rental.getUniqueValue(),
      number: rental.getDisplayValue("u_number"),
      assetName: assetName,
      rentalDate: fmt(rentalDate),
      dueDate: fmt(dueValue),
      isOverdue: !!isOverdue,
      isDueSoon: !!isDueSoon,
      statusLabel: isOverdue ? "Overdue" :
        (isDueSoon ? "Due soon" : "Active"),
      riskLabel: rental.getDisplayValue("u_return_risk") || "Not assessed",
      dueMs: dueValue
        ? new GlideDateTime(dueValue).getNumericValue()
        : 9999999999999
    };

    data.rentals.push(entry);

    if (data.nextRental === null ||
        entry.dueMs < data.nextRental.dueMs) {
      data.nextRental = {
        assetName: entry.assetName,
        dueDate: entry.dueDate,
        dueMs: entry.dueMs
      };
    }
  }

  // Returned rental count.
  var returned = new GlideAggregate("u_student_rental");
  returned.addQuery("u_student", userId);
  returned.addQuery("u_status", "returned");
  returned.addAggregate("COUNT");
  returned.query();

  if (returned.next()) {
    data.returnedCount =
      parseInt(returned.getAggregate("COUNT"), 10) || 0;
  }

  // Hero message based on live rental data.
  if (data.overdueCount > 0) {
    data.messageLabel = "NEEDS YOUR ATTENTION";
    data.messageTitle = data.overdueCount === 1
      ? "Let's get your overdue return sorted."
      : "Let's get those overdue returns sorted.";
    data.messageBody =
      "Check your borrowing shelf for overdue resources and arrange their return.";
    data.messageTone = "danger";
    data.messageIcon = "!";
  } else if (data.dueSoonCount > 0) {
    data.messageLabel = "A LITTLE HEADS-UP";
    data.messageTitle = "Something is due soon.";
    data.messageBody = data.nextRental
      ? data.nextRental.assetName + " is coming up for return. Check its due date and available options."
      : "Check your borrowing shelf for upcoming return dates.";
    data.messageTone = "warn";
    data.messageIcon = "◷";
  } else if (data.activeCount > 0) {
    data.messageLabel = "YOUR BORROWING UPDATE";
    data.messageTitle = "You're all set for now.";
    data.messageBody =
      "Keep enjoying your campus resources. Your active rentals and due dates are ready to review.";
    data.messageTone = "calm";
    data.messageIcon = "✓";
  } else {
    data.messageLabel = "READY FOR YOUR NEXT DISCOVERY?";
    data.messageTitle = "Your borrowing shelf is clear.";
    data.messageBody =
      "Looking for a textbook, laptop, or lab kit? Explore resources available across campus.";
    data.messageTone = "calm";
    data.messageIcon = "✦";
  }

  // Requests belonging to the signed-in student.
  var request = new GlideRecord("sc_req_item");
  request.addQuery("requested_for", userId);
  request.orderByDesc("sys_created_on");
  request.setLimit(5);
  request.query();

  while (request.next()) {
    data.requests.push({
      id: request.getUniqueValue(),
      number: request.getDisplayValue("number"),
      item: request.getDisplayValue("cat_item") || "Catalog item",
      state: request.getDisplayValue("state") || "Submitted",
      created: fmt(request.getValue("sys_created_on"))
    });
  }

  // Available assets and location summaries.
  var asset = new GlideRecord("u_campus_asset");
  asset.addQuery("u_status", "available");
  asset.orderBy("u_asset_name");
  asset.query();

  var locationMap = {};
  var locationOrder = [];
  var assetLimit = 0;

  while (asset.next()) {
    var assetNameValue =
      asset.getDisplayValue("u_asset_name") || "Campus resource";
    var assetTypeValue = asset.getDisplayValue("u_asset_type") || "";
    var locationValue = asset.getDisplayValue("u_location") || "Other locations";

    if (!locationMap[locationValue]) {
      locationMap[locationValue] = {
        name: locationValue,
        count: 0,
        icon: "📍"
      };
      locationOrder.push(locationValue);
    }
    locationMap[locationValue].count++;

    if (data.recommendations.length < 6) {
      var typeLower = assetTypeValue.toLowerCase();
      var icon = "📦";

      if (typeLower.indexOf("book") > -1 ||
          typeLower.indexOf("text") > -1) {
        icon = "📚";
      } else if (typeLower.indexOf("laptop") > -1 ||
                 typeLower.indexOf("computer") > -1) {
        icon = "💻";
      } else if (typeLower.indexOf("lab") > -1 ||
                 typeLower.indexOf("equipment") > -1) {
        icon = "🧪";
      }

      data.recommendations.push({
        id: asset.getUniqueValue(),
        name: assetNameValue,
        type: assetTypeValue,
        location: locationValue,
        icon: icon
      });
    }

    assetLimit++;
  }

  for (var i = 0; i < locationOrder.length && i < 8; i++) {
    data.locations.push(locationMap[locationOrder[i]]);
  }
})();
